<!doctype html><html lang="km"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ផ្ទៀងផ្ទាត់កាតសិស្ស</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card mx-auto" style="max-width:560px"><div class="card-body text-center">@if(!$card)<h2 class="text-danger">Invalid Card</h2><p>មិនអាចរកឃើញកាតនេះទេ។</p>@else<h2 class="{{ $status==='active'?'text-success':'text-danger' }}">{{ $status==='active'?'VALID STUDENT CARD':'CARD '.strtoupper($status) }}</h2><h3>{{ $card->student?->name_kh }}</h3><p>{{ $card->student?->code }}</p><hr><div class="text-start"><p><strong>ក្រុម:</strong> {{ $card->enrollment?->schoolClass?->name }}</p><p><strong>ឆ្នាំសិក្សា:</strong> {{ $card->academicYear?->name }}</p><p><strong>លេខកាត:</strong> {{ $card->card_number }}</p><p><strong>ថ្ងៃចេញ:</strong> {{ $card->issue_date?->format('d/m/Y') }}</p><p><strong>ផុតកំណត់:</strong> {{ $card->expiry_date?->format('d/m/Y') }}</p></div>@endif</div></div></main></body></html>
